186→// FileChanges holds categorized file changes from git status.
187→type FileChanges struct {
188→	Modified []string // Modified or staged files
189→	New      []string // Untracked files (filtered if previouslyUntracked provided)
190→	Deleted  []string // Deleted files (staged or unstaged)
191→}
192→
193→// DetectFileChanges returns categorized file changes from the current git status.
194→//
195→// previouslyUntracked controls new-file detection:
196→//   - nil: all untracked files go into New
197→//   - non-nil: only untracked files NOT in the pre-existing set go into New
198→//
199→// Modified includes both worktree and staging modified/added files.
200→// Deleted includes both staged and unstaged deletions.
201→// All results exclude .entire/ directory.
202→func DetectFileChanges(previouslyUntracked []string) (*FileChanges, error) {
203→	repo, err := openRepository()
204→	if err != nil {
205→		return nil, fmt.Errorf("failed to open repository: %w", err)
206→	}
207→
208→	worktree, err := repo.Worktree()
209→	if err != nil {
210→		return nil, fmt.Errorf("failed to get worktree: %w", err)
211→	}
212→
213→	status, err := worktree.Status()
214→	if err != nil {
215→		return nil, fmt.Errorf("failed to get status: %w", err)
216→	}
217→
218→	// Build set of pre-existing untracked files for quick lookup
219→	var preExisting map[string]bool
220→	if previouslyUntracked != nil {
221→		preExisting = make(map[string]bool, len(previouslyUntracked))
222→		for _, f := range previouslyUntracked {
223→			preExisting[f] = true
224→		}
225→	}
226→
227→	var changes FileChanges
228→	for file, st := range status {
229→		if paths.IsInfrastructurePath(file) {
230→			continue
231→		}
232→
233→		switch {
234→		case st.Worktree == git.Untracked:
235→			if preExisting != nil {
236→				if preExisting[file] {
237→					// Pre-existing untracked file still present: treat as modified.
238→					// Git status can't distinguish content changes in untracked files,
239→					// but the strategy's tree hash dedup will skip if nothing actually changed.
240→					changes.Modified = append(changes.Modified, file)
241→				} else {
242→					changes.New = append(changes.New, file)
243→				}
244→			} else {
245→				changes.New = append(changes.New, file)
246→			}
247→		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
248→			changes.Deleted = append(changes.Deleted, file)
249→		case st.Worktree == git.Modified || st.Staging == git.Modified ||
250→			st.Worktree == git.Added || st.Staging == git.Added:
251→			changes.Modified = append(changes.Modified, file)
252→		}
253→	}
254→
255→	return &changes, nil
256→}
