258→// filterToUncommittedFiles removes files from the list that are already committed to HEAD
259→// with matching content. This prevents re-adding files that an agent committed mid-turn
260→// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
261→// HEAD or with different content in the working tree are kept. Fails open: if any git
262→// operation errors, returns the original list unchanged.
263→func filterToUncommittedFiles(files []string, repoRoot string) []string {
264→	if len(files) == 0 {
265→		return files
266→	}
267→
268→	repo, err := openRepository()
269→	if err != nil {
270→		return files // fail open
271→	}
272→
273→	head, err := repo.Head()
274→	if err != nil {
275→		return files // fail open (empty repo, detached HEAD, etc.)
276→	}
277→
278→	commit, err := repo.CommitObject(head.Hash())
279→	if err != nil {
280→		return files // fail open
281→	}
282→
283→	headTree, err := commit.Tree()
284→	if err != nil {
285→		return files // fail open
286→	}
287→
288→	var result []string
289→	for _, relPath := range files {
290→		headFile, err := headTree.File(relPath)
291→		if err != nil {
292→			// File not in HEAD — it's uncommitted
293→			result = append(result, relPath)
294→			continue
295→		}
296→
297→		// File is in HEAD — compare content with working tree
298→		absPath := filepath.Join(repoRoot, relPath)
299→		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
300→		if err != nil {
301→			// Can't read working tree file (deleted?) — keep it
302→			result = append(result, relPath)
303→			continue
304→		}
305→
306→		headContent, err := headFile.Contents()
307→		if err != nil {
308→			result = append(result, relPath)
309→			continue
310→		}
311→
312→		if string(workingContent) != headContent {
313→			// Working tree differs from HEAD — uncommitted changes
314→			result = append(result, relPath)
315→		}
316→		// else: content matches HEAD — already committed, skip
317→	}
318→
319→	return result
320→}
