349→// getUntrackedFilesForState returns a list of untracked files using go-git
350→// Excludes .entire directory
351→func getUntrackedFilesForState() ([]string, error) {
352→	repo, err := openRepository()
353→	if err != nil {
354→		return nil, err
355→	}
356→
357→	worktree, err := repo.Worktree()
358→	if err != nil {
359→		return nil, err //nolint:wrapcheck // already present in codebase
360→	}
361→
362→	status, err := worktree.Status()
363→	if err != nil {
364→		return nil, err //nolint:wrapcheck // already present in codebase
365→	}
366→
367→	untrackedFiles := []string{}
368→	for file, st := range status {
369→		if st.Worktree == git.Untracked {
370→			// Exclude .entire directory
371→			if !strings.HasPrefix(file, paths.EntireDir+"/") && file != paths.EntireDir {
372→				untrackedFiles = append(untrackedFiles, file)
373→			}
374→		}
375→	}
376→
377→	return untrackedFiles, nil
378→}
