476→// preTaskStateFile returns the absolute path to the pre-task state file for a tool use.
477→// Works correctly from any subdirectory within the repository.
478→func preTaskStateFile(toolUseID string) string {
479→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
480→	if err != nil {
481→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
482→	}
483→	return filepath.Join(tmpDirAbs, fmt.Sprintf("pre-task-%s.json", toolUseID))
484→}
485→
486→// preTaskFilePrefix is the prefix for pre-task state files
487→const preTaskFilePrefix = "pre-task-"
488→
489→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
490→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
491→// When multiple pre-task files exist (nested subagents), returns the most recently
492→// modified one.
493→// Works correctly from any subdirectory within the repository.
494→func FindActivePreTaskFile() (taskToolUseID string, found bool) {
495→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
496→	if err != nil {
497→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
498→	}
499→	entries, err := os.ReadDir(tmpDirAbs)
500→	if err != nil {
501→		return "", false
502→	}
503→
504→	var latestFile string
505→	var latestTime time.Time
506→
507→	for _, entry := range entries {
508→		if entry.IsDir() {
509→			continue
510→		}
511→		name := entry.Name()
512→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
513→			continue
514→		}
515→
516→		// Check modification time for nested subagent handling
517→		info, err := entry.Info()
518→		if err != nil {
519→			continue
520→		}
521→		if latestFile == "" || info.ModTime().After(latestTime) {
522→			latestFile = name
523→			latestTime = info.ModTime()
524→		}
525→	}
526→
527→	if latestFile == "" {
528→		return "", false
529→	}
530→
531→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
532→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
533→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
534→	return toolUseID, true
535→}
