 27→// PromptResponsePair represents a user prompt and the assistant's responses.
 28→// Used for extracting all interactions from a transcript.
 29→type PromptResponsePair struct {
 30→	Prompt    string
 31→	Responses []string // Multiple responses can occur between tool calls
 32→	Files     []string
 33→}
 34→
 35→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
 36→// Returns pairs in chronological order (oldest first).
 37→// Each pair contains the user's prompt, assistant's text response, and files modified.
 38→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
 39→	var pairs []PromptResponsePair
 40→
 41→	// Find all user prompts (messages with string content, not tool results)
 42→	var userIndices []int
 43→	for i, line := range transcript {
 44→		if line.Type == transcriptTypeUser {
 45→			var msg userMessage
 46→			if err := json.Unmarshal(line.Message, &msg); err != nil {
 47→				continue
 48→			}
 49→			// Only count messages with string content (real user prompts)
 50→			if _, ok := msg.Content.(string); ok {
 51→				userIndices = append(userIndices, i)
 52→			} else if arr, ok := msg.Content.([]interface{}); ok {
 53→				// Check if array has text blocks (also a real user prompt)
 54→				for _, item := range arr {
 55→					if m, ok := item.(map[string]interface{}); ok {
 56→						if m["type"] == contentTypeText {
 57→							userIndices = append(userIndices, i)
 58→							break
 59→						}
 60→					}
 61→				}
 62→			}
 63→		}
 64→	}
 65→
 66→	// For each user prompt, extract the prompt text, following assistant response, and files
 67→	for idx, userIdx := range userIndices {
 68→		// Determine the range for this prompt's conversation
 69→		endIdx := len(transcript)
 70→		if idx < len(userIndices)-1 {
 71→			endIdx = userIndices[idx+1]
 72→		}
 73→
 74→		// Extract prompt text
 75→		prompt := extractUserPromptAt(transcript, userIdx)
 76→		if prompt == "" {
 77→			continue
 78→		}
 79→
 80→		// Extract assistant responses and files from this range
 81→		slice := transcript[userIdx:endIdx]
 82→		responses := extractAssistantResponses(slice)
 83→		files := extractModifiedFiles(slice)
 84→
 85→		pairs = append(pairs, PromptResponsePair{
 86→			Prompt:    prompt,
 87→			Responses: responses,
 88→			Files:     files,
 89→		})
 90→	}
 91→
 92→	return pairs
 93→}
