 95→// extractUserPromptAt extracts the user prompt at the given index.
 96→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
 97→func extractUserPromptAt(lines []transcriptLine, idx int) string {
 98→	if idx >= len(lines) || lines[idx].Type != transcriptTypeUser {
 99→		return ""
100→	}
101→
102→	return transcript.ExtractUserContent(lines[idx].Message)
103→}
