105→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
106→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
107→func extractAssistantResponses(transcript []transcriptLine) []string {
108→	var texts []string
109→	for _, line := range transcript {
110→		if line.Type == transcriptTypeAssistant {
