package checkpoint

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// changeTree represents pending changes to apply to a git tree incrementally.
// Only changed paths are traversed; unchanged subtrees are reused by hash reference.
type changeTree struct {
	dirs  map[string]*changeTree // subdirectory changes
	files map[string]*fileChange // file changes in this directory
}

// fileChange represents a single file addition, update, or deletion.
type fileChange struct {
	hash   plumbing.Hash
	mode   filemode.FileMode
	delete bool
}

func newChangeTree() *changeTree {
	return &changeTree{
		dirs:  make(map[string]*changeTree),
		files: make(map[string]*fileChange),
	}
}

// addFile records a file addition or update in the change tree.
// The path uses forward slashes as separators (git convention).
func (ct *changeTree) addFile(path string, hash plumbing.Hash, mode filemode.FileMode) {
	parts := strings.Split(path, "/")
	node := ct
	for _, part := range parts[:len(parts)-1] {
		if _, ok := node.dirs[part]; !ok {
			node.dirs[part] = newChangeTree()
		}
		node = node.dirs[part]
	}
	node.files[parts[len(parts)-1]] = &fileChange{hash: hash, mode: mode}
}

// deleteFile records a file deletion in the change tree.
func (ct *changeTree) deleteFile(path string) {
	parts := strings.Split(path, "/")
	node := ct
	for _, part := range parts[:len(parts)-1] {
		if _, ok := node.dirs[part]; !ok {
			node.dirs[part] = newChangeTree()
		}
		node = node.dirs[part]
	}
	node.files[parts[len(parts)-1]] = &fileChange{delete: true}
}

// isEmpty returns true if the change tree has no pending changes.
func (ct *changeTree) isEmpty() bool {
	return len(ct.dirs) == 0 && len(ct.files) == 0
}

// applyChangesToTree merges a changeTree into a base git tree, returning the new root tree hash.
// Only directories containing changes are rebuilt; unchanged subtrees are reused by hash reference.
// This is O(changed_files * tree_depth) instead of O(total_files_in_repo).
func applyChangesToTree(repo *git.Repository, baseTreeHash plumbing.Hash, changes *changeTree) (plumbing.Hash, error) {
	if changes.isEmpty() {
		return baseTreeHash, nil
	}

	baseTree, err := repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get tree: %w", err)
	}

	// Track which change entries we've processed (matched to existing tree entries)
	processedDirs := make(map[string]bool)
	processedFiles := make(map[string]bool)

	var newEntries []object.TreeEntry

	// Process existing entries
	for _, entry := range baseTree.Entries {
		if entry.Mode == filemode.Dir {
			if dirChanges, ok := changes.dirs[entry.Name]; ok {
				// Recurse into subdirectory with changes
				newSubHash, subErr := applyChangesToTree(repo, entry.Hash, dirChanges)
				if subErr != nil {
					return plumbing.ZeroHash, subErr
				}
				newEntries = append(newEntries, object.TreeEntry{
					Name: entry.Name,
					Mode: filemode.Dir,
					Hash: newSubHash,
				})
				processedDirs[entry.Name] = true
			} else if fileChange, ok := changes.files[entry.Name]; ok {
				// Type conflict: base has dir, changes has file → replace dir with file
				if !fileChange.delete {
					newEntries = append(newEntries, object.TreeEntry{
						Name: entry.Name,
						Mode: fileChange.mode,
						Hash: fileChange.hash,
					})
				}
				processedFiles[entry.Name] = true
			} else {
				// No changes in this directory, keep as-is
				newEntries = append(newEntries, entry)
			}
		} else {
			// File entry
			if change, ok := changes.files[entry.Name]; ok {
				if !change.delete {
					newEntries = append(newEntries, object.TreeEntry{
						Name: entry.Name,
						Mode: change.mode,
						Hash: change.hash,
					})
				}
				// If delete: don't add to newEntries
				processedFiles[entry.Name] = true
			} else if dirChanges, ok := changes.dirs[entry.Name]; ok {
				// Type conflict: base has file, changes has dir → replace file with dir
				newSubHash, subErr := createTreeFromChanges(repo, dirChanges)
				if subErr != nil {
					return plumbing.ZeroHash, subErr
				}
				if newSubHash != plumbing.ZeroHash {
					newEntries = append(newEntries, object.TreeEntry{
						Name: entry.Name,
						Mode: filemode.Dir,
						Hash: newSubHash,
					})
				}
				processedDirs[entry.Name] = true
			} else {
				// No change, keep as-is
				newEntries = append(newEntries, entry)
			}
		}
	}

	// Add new files (not in base tree)
	for name, change := range changes.files {
		if !processedFiles[name] && !change.delete {
			newEntries = append(newEntries, object.TreeEntry{
				Name: name,
				Mode: change.mode,
				Hash: change.hash,
			})
		}
	}

	// Add new directories (not in base tree)
	for name, dirChanges := range changes.dirs {
		if !processedDirs[name] {
			newSubHash, subErr := createTreeFromChanges(repo, dirChanges)
			if subErr != nil {
				return plumbing.ZeroHash, subErr
			}
			// Skip empty trees (e.g., all changes were deletions for non-existent paths)
			if newSubHash == plumbing.ZeroHash {
				continue
			}
			newEntries = append(newEntries, object.TreeEntry{
				Name: name,
				Mode: filemode.Dir,
				Hash: newSubHash,
			})
		}
	}

	sortTreeEntries(newEntries)
	return storeTree(repo, newEntries)
}

// createTreeFromChanges creates a new tree from a changeTree with no base tree.
// Used for new directories that don't exist in the base tree.
func createTreeFromChanges(repo *git.Repository, changes *changeTree) (plumbing.Hash, error) {
	var entries []object.TreeEntry

	for name, change := range changes.files {
		if !change.delete {
			entries = append(entries, object.TreeEntry{
				Name: name,
				Mode: change.mode,
				Hash: change.hash,
			})
		}
	}

	for name, dirChanges := range changes.dirs {
		subHash, err := createTreeFromChanges(repo, dirChanges)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		// Skip empty subtrees (all files were deletions)
		if subHash == plumbing.ZeroHash {
			continue
		}
		entries = append(entries, object.TreeEntry{
			Name: name,
			Mode: filemode.Dir,
			Hash: subHash,
		})
	}

	// If all entries were deletions, don't create an empty tree
	if len(entries) == 0 {
		return plumbing.ZeroHash, nil
	}

	sortTreeEntries(entries)
	return storeTree(repo, entries)
}

// storeTree creates and stores a git tree object from entries.
func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
	tree := &object.Tree{Entries: entries}
	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}
	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}
	return hash, nil
}

// addDirectoryToChangeTree walks a filesystem directory and adds all files to a changeTree.
// dirPathAbs is the absolute path for reading files, dirPathRel is the git tree path prefix.
func addDirectoryToChangeTree(repo *git.Repository, dirPathAbs, dirPathRel string, ct *changeTree) error {
	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if info.IsDir() {
			return nil
		}

		relWithinDir, relErr := filepath.Rel(dirPathAbs, path)
		if relErr != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, relErr)
		}

		blobHash, mode, blobErr := createBlobFromFile(repo, path)
		if blobErr != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, blobErr)
		}

		// Use forward slashes for git tree paths
		treePath := filepath.ToSlash(dirPathRel) + "/" + filepath.ToSlash(relWithinDir)
		ct.addFile(treePath, blobHash, mode)
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
	}
	return nil
}

package cli

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	agentpkg "github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/textutil"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// Transcript message type constants - aliases to transcript package for local use.
const (
	transcriptTypeUser      = transcript.TypeUser
	transcriptTypeAssistant = transcript.TypeAssistant
	contentTypeText         = transcript.ContentTypeText
	contentTypeToolUse      = transcript.ContentTypeToolUse
)

// PromptResponsePair represents a user prompt and the assistant's responses.
// Used for extracting all interactions from a transcript.
type PromptResponsePair struct {
	Prompt    string
	Responses []string // Multiple responses can occur between tool calls
	Files     []string
}

// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
// Returns pairs in chronological order (oldest first).
// Each pair contains the user's prompt, assistant's text response, and files modified.
func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
	var pairs []PromptResponsePair

	// Find all user prompts (messages with string content, not tool results)
	var userIndices []int
	for i, line := range transcript {
		if line.Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (real user prompts)
			if _, ok := msg.Content.(string); ok {
				userIndices = append(userIndices, i)
			} else if arr, ok := msg.Content.([]interface{}); ok {
				// Check if array has text blocks (also a real user prompt)
				for _, item := range arr {
					if m, ok := item.(map[string]interface{}); ok {
						if m["type"] == contentTypeText {
							userIndices = append(userIndices, i)
							break
						}
					}
				}
			}
		}
	}

	// For each user prompt, extract the prompt text, following assistant response, and files
	for idx, userIdx := range userIndices {
		// Determine the range for this prompt's conversation
		endIdx := len(transcript)
		if idx < len(userIndices)-1 {
			endIdx = userIndices[idx+1]
		}

		// Extract prompt text
		prompt := extractUserPromptAt(transcript, userIdx)
		if prompt == "" {
			continue
		}

		// Extract assistant responses and files from this range
		slice := transcript[userIdx:endIdx]
		responses := extractAssistantResponses(slice)
		files := extractModifiedFiles(slice)

		pairs = append(pairs, PromptResponsePair{
			Prompt:    prompt,
			Responses: responses,
			Files:     files,
		})
	}

	return pairs
}

// extractUserPromptAt extracts the user prompt at the given index.
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractUserPromptAt(lines []transcriptLine, idx int) string {
	if idx >= len(lines) || lines[idx].Type != transcriptTypeUser {
		return ""
	}

	return transcript.ExtractUserContent(lines[idx].Message)
}

// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
// A single prompt can trigger multiple assistant responses interspersed with tool calls.
func extractAssistantResponses(transcript []transcriptLine) []string {
	var texts []string
	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeText && block.Text != "" {
					texts = append(texts, block.Text)
				}
			}
		}
	}
	return texts
}

// extractUserPrompts extracts all user messages from the transcript in order.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
func extractUserPrompts(transcript []transcriptLine) []string {
	var prompts []string
	for i := range transcript {
		if transcript[i].Type != transcriptTypeUser {
			continue
		}
		var msg userMessage
		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
			continue
		}

		// Handle string content
		if str, ok := msg.Content.(string); ok {
			prompts = append(prompts, textutil.StripIDEContextTags(str))
			continue
		}

		// Handle array content (only if it contains text blocks)
		if arr, ok := msg.Content.([]interface{}); ok {
			var texts []string
			for _, item := range arr {
				if m, ok := item.(map[string]interface{}); ok {
					if m["type"] == contentTypeText {
						if text, ok := m["text"].(string); ok {
							texts = append(texts, text)
						}
					}
				}
			}
			if len(texts) > 0 {
				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
			}
		}
	}
	return prompts
}

// extractLastUserPrompt extracts the last user message from the transcript.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractLastUserPrompt(transcript []transcriptLine) string {
	prompts := extractUserPrompts(transcript)
	if len(prompts) == 0 {
		return ""
	}
	return prompts[len(prompts)-1]
}

// findLastUserUUID finds the UUID of the last user message (that has string content)
func findLastUserUUID(transcript []transcriptLine) string {
	for i := len(transcript) - 1; i >= 0; i-- {
		if transcript[i].Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (not tool results)
			if _, ok := msg.Content.(string); ok {
				return transcript[i].UUID
			}
		}
	}
	return ""
}

// filterTranscriptAfterUUID returns transcript lines after the given UUID
func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	foundIndex := -1
	for i, line := range transcript {
		if line.UUID == uuid {
			foundIndex = i
			break
		}
	}

	if foundIndex == -1 || foundIndex == len(transcript)-1 {
		return transcript
	}

	return transcript[foundIndex+1:]
}

// extractModifiedFiles extracts the list of files modified by tool calls
func extractModifiedFiles(transcript []transcriptLine) []string {
	fileSet := make(map[string]bool)
	var files []string

	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeToolUse {
					isModifyTool := false
					for _, name := range claudecode.FileModificationTools {
						if block.Name == name {
							isModifyTool = true
							break
						}
					}

					if isModifyTool {
						var input toolInput
						if err := json.Unmarshal(block.Input, &input); err != nil {
							continue
						}

						file := input.FilePath
						if file == "" {
							file = input.NotebookPath
						}

						if file != "" && !fileSet[file] {
							fileSet[file] = true
							files = append(files, file)
						}
					}
				}
			}
		}
	}

	return files
}

// resolveTranscriptPath determines the correct file path for an agent's session transcript.
// Computes the path dynamically from the current repo location for cross-machine portability.
func resolveTranscriptPath(sessionID string, agent agentpkg.Agent) (string, error) {
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return "", fmt.Errorf("failed to get repository root: %w", err)
	}

	sessionDir, err := agent.GetSessionDir(repoRoot)
	if err != nil {
		return "", fmt.Errorf("failed to get agent session directory: %w", err)
	}
	return agent.ResolveSessionFile(sessionDir, sessionID), nil
}


// AgentTranscriptPath returns the path to a subagent's transcript file.
// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
// as the main transcript.
func AgentTranscriptPath(transcriptDir, agentID string) string {
	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
}

// toolResultBlock represents a tool_result in a user message
type toolResultBlock struct {
	Type      string `json:"type"`
	ToolUseID string `json:"tool_use_id"`
}

// userMessageWithToolResults represents a user message that may contain tool results
type userMessageWithToolResults struct {
	Content []toolResultBlock `json:"content"`
}

// FindCheckpointUUID finds the UUID of the message containing the tool_result
// for the given tool_use_id. This is used to find the checkpoint point for
// transcript truncation when rewinding to a task.
// Returns the UUID and true if found, empty string and false otherwise.
func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
	for _, line := range transcript {
		if line.Type != transcriptTypeUser {
			continue
		}

		var msg userMessageWithToolResults
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
				return line.UUID, true
			}
		}
	}
	return "", false
}

// TruncateTranscriptAtUUID returns transcript lines up to and including the
// line with the given UUID. If the UUID is not found or is empty, returns
// the entire transcript.
//
//nolint:revive // Exported for testing purposes
func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	for i, line := range transcript {
		if line.UUID == uuid {
			return transcript[:i+1]
		}
	}

	// UUID not found, return full transcript
	return transcript
}

// writeTranscript writes transcript lines to a file in JSONL format.
func writeTranscript(path string, transcript []transcriptLine) error {
	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer func() { _ = file.Close() }()

	for _, line := range transcript {
		data, err := json.Marshal(line)
		if err != nil {
			return fmt.Errorf("failed to marshal line: %w", err)
		}
		if _, err := file.Write(data); err != nil {
			return fmt.Errorf("failed to write line: %w", err)
		}
		if _, err := file.WriteString("\n"); err != nil {
			return fmt.Errorf("failed to write newline: %w", err)
		}
	}

	return nil
}

// TranscriptPosition contains the position information for a transcript file.
type TranscriptPosition struct {
	LastUUID  string // Last non-empty UUID (from user/assistant messages)
	LineCount int    // Total number of lines
}

// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
// Returns empty position if file doesn't exist or is empty.
// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
func GetTranscriptPosition(path string) (TranscriptPosition, error) {
	if path == "" {
		return TranscriptPosition{}, nil
	}

	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
	if err != nil {
		if os.IsNotExist(err) {
			return TranscriptPosition{}, nil
		}
		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
	}
	defer func() { _ = file.Close() }()

	var pos TranscriptPosition
	reader := bufio.NewReader(file)

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
		}

		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		pos.LineCount++

		// Parse line to extract UUID (only from user/assistant messages, not summaries)
		var line transcriptLine
		if err := json.Unmarshal(lineBytes, &line); err == nil {
			if line.UUID != "" {
				pos.LastUUID = line.UUID
			}
		}

		if err == io.EOF {
			break
		}
	}

	return pos, nil
}

